WITH flattened_attrs AS (SELECT id, service, host, log_ts, level, status_code, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, COALESCE(context['version'], 'direct') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, CASE WHEN duration_sec >= 3.4 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, COUNT(*) AS row_count, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN service = 'auth' THEN 1 END), 0), 2) AS status_code_per_auth FROM flattened_attrs GROUP BY 1, 2 ORDER BY row_count
